Boolean dstcrypt_write_isk (const UInt8 * isk , UInt8 size)        
{         
 

  if(dstcrypt_set_isk(isk,size))	   
    {      
      if(nvfs_wr_create(nvfs_dst_isk , &dstcrypt_nvfs_entry , sizeof(DstCrypt_Nvfs_Entry)) == NVFS_OK )
	  {
	      dstcrypt_init_nvfs() ;//dstcrypt_vars.nvfs_entry_done = TRUE; 
		
          #if DBG_DSTCRYPT == 1
            dstcrypt_dbg_print("\nDstCrypt Isk Write Done" , NULL , NULL) ;
          #endif 

          return TRUE;
	 }
     else
       {
         #if DBG_DSTCRYPT == 1
           dstcrypt_dbg_print("\nDstCrypt Isk Write Create FAIL" , NULL , NULL) ;
         #endif    
       }   
    }
  return FALSE ;
}
